#nullable enable // autogenerated

using MVZ2.GameContent.Damages;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Shells;
using PVZEngine.Damages;
using PVZEngine.Definitions;
using PVZEngine.Shells;

namespace MVZ2.GameContent.Shells
{
    [AutoShellDefinition(VanillaShellNames.bubble)]
    public class BubbleShell : ShellDefinition
    {
        public BubbleShell(string nsp, string name) : base(nsp, name)
        {
            SetProperty(VanillaShellProps.SLICE_CRITICAL, true);
            SetProperty(VanillaShellProps.HIT_SOUND, VanillaSoundID.bubbleHit);
            SetProperty(VanillaShellProps.DENSITY, 0f);
        }
        public override void EvaluateDamage(DamageInputPart input)
        {
            base.EvaluateDamage(input);
            if (input.Effects.HasEffect(VanillaDamageEffects.SLICE) || input.Effects.HasEffect(VanillaDamageEffects.POINTY) || input.Effects.HasEffect(VanillaDamageEffects.GROUND_SPIKES))
            {
                input.Multiply(20);
            }
            if (input.Effects.HasEffect(VanillaDamageEffects.ICE) || input.Effects.HasEffect(VanillaDamageEffects.SLOW))
            {
                input.Multiply(20);
            }
        }
    }
}
